<?php
require_once __DIR__.'/includes/panel_helpers.php';exigirRol([1]);require_once __DIR__.'/../config/database.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location: medicos_moderno.php');exit;}if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));
try{$pdo=conectarBD();$s=$pdo->prepare('SELECT * FROM medicos WHERE id=:id');$s->execute(['id'=>$id]);$medico=$s->fetch();if(!$medico){http_response_code(404);exit('Médico no encontrado.');}$especialidades=$pdo->query('SELECT id,nombre FROM especialidades WHERE activo=TRUE ORDER BY nombre')->fetchAll();$s=$pdo->prepare('SELECT especialidad_id FROM medicos_especialidades WHERE medico_id=:id');$s->execute(['id'=>$id]);$asignadas=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable $e){error_log($e->getMessage());http_response_code(500);exit('No se pudo cargar el médico.');}
require_once __DIR__.'/includes/layout.php';renderSidebar('medicos');?>
<div class="payment-form-shell"><div class="doctor-page-heading"><div><span class="doctor-eyebrow">Administración de profesionales</span><h1>Editar médico</h1><p>Actualiza sus datos y especialidades asignadas.</p></div><a class="btn btn-secondary" href="medicos_moderno.php">Volver</a></div><?php if(isset($_GET['error'])):?><div class="alert alert-error"><?= ($_GET['error']==='duplicado')?'La licencia o el correo ya pertenece a otro médico.':'Revisa los datos ingresados.' ?></div><?php endif;?><section class="card"><div class="card-body"><form action="actualizar_medico.php" method="POST" class="stack"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><div class="form-grid"><div class="form-group"><label class="form-label required" for="nombres">Nombres</label><input class="form-input" id="nombres" name="nombres" maxlength="100" required value="<?= h($medico['nombres']) ?>"></div><div class="form-group"><label class="form-label required" for="apellidos">Apellidos</label><input class="form-input" id="apellidos" name="apellidos" maxlength="100" required value="<?= h($medico['apellidos']) ?>"></div><div class="form-group"><label class="form-label required" for="licencia">Número de licencia</label><input class="form-input" id="licencia" name="numero_licencia" maxlength="80" required value="<?= h($medico['numero_licencia']) ?>"></div><div class="form-group"><label class="form-label" for="telefono">Teléfono</label><input class="form-input" id="telefono" name="telefono" maxlength="30" value="<?= h($medico['telefono']??'') ?>"></div><div class="form-group"><label class="form-label" for="correo">Correo</label><input class="form-input" id="correo" type="email" name="correo" maxlength="255" value="<?= h($medico['correo']??'') ?>"></div><div class="form-group"><label class="form-label" for="consultorio">Consultorio</label><input class="form-input" id="consultorio" name="consultorio" maxlength="100" value="<?= h($medico['consultorio']??'') ?>"></div><div class="form-group form-span-2"><label class="form-label" for="sede">Sede o ubicación</label><input class="form-input" id="sede" name="sede" maxlength="150" value="<?= h($medico['sede']??'') ?>"></div></div><fieldset class="specialty-fieldset"><legend>Especialidades</legend><div class="specialty-check-grid"><?php foreach($especialidades as $e):?><label><input type="checkbox" name="especialidades[]" value="<?= (int)$e['id'] ?>" <?= in_array((int)$e['id'],$asignadas,true)?'checked':'' ?>> <span><?= h($e['nombre']) ?></span></label><?php endforeach;?></div></fieldset><button class="btn btn-primary" type="submit">Guardar cambios</button></form></div></section></div><?php renderFooter();?>
